import type { Metadata } from 'next'
import { AccesoForm } from '@/components/infraestructura/acceso-form'
import { EncabezadoParte, TITULO_PROGRAMA_COMPLETO } from '@/components/infraestructura/encabezado-parte'
import { EstadoActualParte } from '@/components/infraestructura/estado-actual-parte'
import { tieneAccesoAlParteDesdeCookies } from '@/lib/infraestructura/acceso-parte'
import { resolverContextoPorCue, type ContextoErrorKind } from '@/lib/infraestructura/contexto'
import { ensureGeSchema, openGeDb } from '@/lib/infraestructura/ge-db'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export const metadata: Metadata = {
  title: `Estado actual · ${TITULO_PROGRAMA_COMPLETO}`,
}

const TITULO = 'Estado actual'

// Mismos textos que app/(publico)/problematicas/nueva/page.tsx: el director
// no debería leer dos explicaciones distintas del mismo problema según por
// qué enlace entró.
const MENSAJES_ERROR: Record<ContextoErrorKind, string> = {
  cue_ausente: 'Este enlace no incluye el CUE de la escuela. Solicite el enlace nuevamente a quien se lo compartió.',
  cue_invalido: 'El CUE incluido en el enlace no tiene un formato válido.',
  sin_corte_vigente: 'No hay datos de escuelas disponibles en este momento. Intente nuevamente más tarde.',
  cue_inexistente: 'No se encontró una escuela con ese CUE.',
  sin_secciones: 'Esta escuela todavía no tiene secciones cargadas.',
}

/**
 * Pantalla inicial del director (spec §6): muestra el estado actual ANTES de
 * cualquier formulario (spec §5.1, "Mostrar antes de pedir").
 *
 * La página resuelve la guarda de acceso y la identificación del
 * establecimiento — punto 1 de §6 — para que el director reconozca dónde está
 * parado sin esperar a la red. El resto del parte lo pide el componente
 * cliente contra el Route Handler, como el resto del recorrido público (no
 * hay server actions en el proyecto).
 */
export default async function EstadoActualPartePage({
  searchParams,
}: {
  searchParams: Promise<{ cue?: string }>
}) {
  const { cue } = await searchParams

  if (!(await tieneAccesoAlParteDesdeCookies())) {
    return (
      <div className="publico-content">
        <EncabezadoParte pantalla={TITULO} />
        <AccesoForm />
      </div>
    )
  }

  const client = openGeDb()
  let resultado
  try {
    await ensureGeSchema(client)
    resultado = await resolverContextoPorCue(client, cue ?? null)
  } finally {
    client.close()
  }

  if (!resultado.ok) {
    return (
      <div className="publico-content">
        <EncabezadoParte pantalla={TITULO} />
        <p className="estado-actual-aviso__texto" role="alert">
          {MENSAJES_ERROR[resultado.error.kind]}
        </p>
      </div>
    )
  }

  const { escuela } = resultado.contexto

  return (
    <div className="publico-content publico-content--ancho">
      {/* §6.1 — Identificación del establecimiento, ahora subordinada al
          título del programa: el enlace ya puso al director en su escuela. */}
      <EncabezadoParte pantalla={TITULO} escuela={escuela} />

      <EstadoActualParte cue={escuela.cueAnexo} />
    </div>
  )
}

// @vitest-environment jsdom
import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { render, screen } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { ensureGeSchema, openGeDb } from '@/lib/infraestructura/ge-db'
import { claveDePrueba } from '@/lib/infraestructura/claves-de-prueba'

const CLAVE = claveDePrueba()

const cookiesGetMock = vi.fn()
vi.mock('next/headers', () => ({
  cookies: async () => ({ get: cookiesGetMock }),
}))
// Sin sesión: 'sin cookie de acceso' tiene que seguir mostrando el ingreso.
vi.mock('@/lib/session', () => ({ getSessionUser: async () => null }))
vi.mock('next/navigation', () => ({
  useRouter: () => ({ refresh: vi.fn() }),
}))

const { default: NuevoPartePage } = await import('./page')
const { crearTokenSesion } = await import('@/lib/infraestructura/acceso-publico')

let dir: string
let prevDataDir: string | undefined
let prevPassword: string | undefined

beforeEach(() => {
  dir = mkdtempSync(path.join(tmpdir(), 'parte-nuevo-page-'))
  prevDataDir = process.env.DATA_DIR
  prevPassword = process.env.PROBLEMATICAS_ACCESO_PASSWORD
  process.env.DATA_DIR = dir
  process.env.PROBLEMATICAS_ACCESO_PASSWORD = CLAVE
  cookiesGetMock.mockReset()
})

afterEach(() => {
  if (prevDataDir === undefined) delete process.env.DATA_DIR
  else process.env.DATA_DIR = prevDataDir
  if (prevPassword === undefined) delete process.env.PROBLEMATICAS_ACCESO_PASSWORD
  else process.env.PROBLEMATICAS_ACCESO_PASSWORD = prevPassword
  rmSync(dir, { recursive: true, force: true })
  document.body.innerHTML = ''
})

function conAcceso() {
  const { token } = crearTokenSesion()
  cookiesGetMock.mockReturnValue({ value: token })
}

async function seedEscuelaConSeccion() {
  const client = openGeDb()
  try {
    await ensureGeSchema(client)
    await client.execute(
      "INSERT INTO ge_corte (id, ciclo_lectivo, fetched_at, estado) VALUES (1, 2026, '2026-03-01T00:00:00Z', 'vigente')",
    )
    await client.execute(
      "INSERT INTO ge_localizacion (cue_anexo, cui, nombre, departamento, localidad) VALUES ('1801605-04', NULL, 'Escuela 4', 'Entre Rios', 'Parana')",
    )
    await client.execute(
      "INSERT INTO ge_seccion (corte_id, ge_section_id, cue_anexo, curso, division, nivel, turno) VALUES (1, 10, '1801605-04', '1', 'A', 'Primario', 'Mañana')",
    )
    await client.execute('INSERT INTO ge_alumno_seccion (corte_id, ge_section_id, ge_person_id) VALUES (1, 10, 900001)')
  } finally {
    client.close()
  }
}

describe('NuevoPartePage', () => {
  it('sin cookie de acceso, muestra la pantalla de ingreso en vez del formulario', async () => {
    await seedEscuelaConSeccion()
    cookiesGetMock.mockReturnValue(undefined)

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '1801605-04' }) })
    render(jsx)

    expect(screen.getByLabelText(/contraseña/i)).toBeInTheDocument()
    expect(screen.queryByText('Escuela 4')).not.toBeInTheDocument()
  })

  it('con cookie de acceso vigente, encabeza con el programa y abre el asistente', async () => {
    await seedEscuelaConSeccion()
    conAcceso()

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '1801605-04' }) })
    render(jsx)

    // El título es el del programa; la escuela queda como identidad
    // subordinada, una sola vez y sin encabezar la pantalla.
    expect(
      screen.getByRole('heading', { level: 1, name: 'Registro de Incidencias ENOS 2026/2027' }),
    ).toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: 'Escuela 4' })).toBeNull()
    expect(screen.getByText('Escuela 4')).toBeInTheDocument()

    expect(screen.getByText('Paso 1 de 4')).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: /agregar afectación/i })).toBeNull()
  })

  it('muestra un error claro sin CUE, sin ofrecer alternativas', async () => {
    await seedEscuelaConSeccion()
    conAcceso()

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({}) })
    render(jsx)

    expect(screen.getByText(/no incluye el CUE/i)).toBeInTheDocument()
    expect(screen.queryByText(/1801605/)).not.toBeInTheDocument()
  })

  it('muestra un error claro para un CUE inexistente', async () => {
    await seedEscuelaConSeccion()
    conAcceso()

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '9999999' }) })
    render(jsx)

    expect(screen.getByText(/no se encontró una escuela/i)).toBeInTheDocument()
  })
})

import { cookies } from 'next/headers'
import { getSessionUser } from '@/lib/session'
import {
  NOMBRE_COOKIE,
  tieneAccesoPublico,
  tieneAccesoPublicoDesdeValorCookie,
} from '@/lib/infraestructura/acceso-publico'
import {
  extraerCookieVerificacionSesion,
  NOMBRE_COOKIE_SESION_VERIFICACION,
  verificacionIdDeSesionValida,
} from '@/lib/infraestructura/verificacion-sesion'
import { verificacionHabilitaSesionEscritura } from '@/lib/infraestructura/verificaciones'

/*
  Guarda del recorrido del parte: contraseña pública O sesión de administrador.

  Por qué existe este módulo y no un cambio dentro de acceso-publico.ts: ese
  archivo se declara la única costura con el mundo público y promete que el día
  que llegue la autenticación por token se reescribe él solo, sin tocar a sus
  llamadores. Meterle la sesión del hub adentro rompería esa promesa —pasaría a
  depender de la base y del rol—, así que la composición vive acá, una capa
  arriba, y él sigue siendo sólo contraseña.

  El rol es 'admin' y no isStaff(): la contraseña se puso porque el contexto del
  parte incluye identidad de alumnos, y ese mismo dato ya tiene una regla de
  acceso escrita en permiso-nominal.ts, donde 'admin' entra sin grant y 'editor'
  queda afuera a propósito. Abrirle la puerta a 'editor' acá contradiría esa
  decisión por la ventana de al lado.

  El orden importa: primero la contraseña, que es una verificación HMAC en
  memoria, y sólo si falla se resuelve la sesión, que consulta la base. Así el
  director —que es quien más entra— nunca paga ese viaje.
*/

async function esAdministrador(): Promise<boolean> {
  const user = await getSessionUser()
  return Boolean(user && !user.banned && user.role === 'admin')
}

/** Para Route Handlers, que reciben la cookie dentro del Request. */
export async function tieneAccesoAlParte(request: Request): Promise<boolean> {
  if (tieneAccesoPublico(request)) return true
  return esAdministrador()
}

/** Para páginas del App Router, que leen la cookie del store de la request. */
export async function tieneAccesoAlParteDesdeCookies(): Promise<boolean> {
  const cookieStore = await cookies()
  if (tieneAccesoPublicoDesdeValorCookie(cookieStore.get(NOMBRE_COOKIE)?.value)) return true
  return esAdministrador()
}

/**
 * Acceso acotado al CUE exacto de una verificación (batch E1): un director
 * que entró por el enlace de "Hay afectación" puede usar el formulario de
 * parte SIN la contraseña compartida, pero SÓLO para ese CUE y sólo mientras
 * la sesión canjeada del token no venció. Nunca amplía a otro CUE ni a rol
 * admin — ver verificacion-sesion.ts para el alcance exacto.
 */
export async function tieneAccesoAlParteParaCue(request: Request, cueAnexo: string): Promise<boolean> {
  if (await tieneAccesoAlParte(request)) return true
  const cookieHeader = request.headers.get('cookie')
  const valor = extraerCookieVerificacionSesion(cookieHeader)
  const verificacionId = verificacionIdDeSesionValida(valor, cueAnexo)
  if (!verificacionId) return false
  return verificacionHabilitaSesionEscritura(verificacionId)
}

/** Para Server Components (app/problematicas/parte/page.tsx). */
export async function tieneAccesoAlParteParaCueDesdeCookies(cueAnexo: string): Promise<boolean> {
  if (await tieneAccesoAlParteDesdeCookies()) return true
  const cookieStore = await cookies()
  const valor = cookieStore.get(NOMBRE_COOKIE_SESION_VERIFICACION)?.value
  const verificacionId = verificacionIdDeSesionValida(valor, cueAnexo)
  if (!verificacionId) return false
  return verificacionHabilitaSesionEscritura(verificacionId)
}

import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { eq } from 'drizzle-orm'
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'
import { claveDePrueba } from '@/lib/infraestructura/claves-de-prueba'
import { getDb } from '@/lib/db'
import { infraVerificacion } from '@/lib/db/schema'
import { ensureSeeded, PERIODO_ENOS_2026_2027_ID } from '@/lib/db/seed'
import { crearEpisodio } from '@/lib/infraestructura/episodios'
import {
  cancelarVerificacion,
  crearVerificacion,
  responderPorEnlace,
} from '@/lib/infraestructura/verificaciones'

const getSessionUserMock = vi.fn()
const cookiesGetMock = vi.fn()

vi.mock('@/lib/session', () => ({
  getSessionUser: () => getSessionUserMock(),
}))

vi.mock('next/headers', () => ({
  cookies: async () => ({ get: cookiesGetMock }),
}))

const {
  tieneAccesoAlParte,
  tieneAccesoAlParteDesdeCookies,
  tieneAccesoAlParteParaCue,
  tieneAccesoAlParteParaCueDesdeCookies,
} = await import('@/lib/infraestructura/acceso-parte')
const { NOMBRE_COOKIE, crearTokenSesion } = await import('@/lib/infraestructura/acceso-publico')
const { NOMBRE_COOKIE_SESION_VERIFICACION, crearSesionVerificacion } = await import(
  '@/lib/infraestructura/verificacion-sesion'
)

// Base real en un tmpdir (mismo patrón que lib/infraestructura/verificaciones.test.ts)
// para los tests de re-chequeo contra la fila de la verificación. El resto del
// archivo sigue sin tocar la base: contraseña pública y rol admin no la consultan.
let dir: string
let prevDataDir: string | undefined

beforeAll(async () => {
  dir = mkdtempSync(path.join(tmpdir(), 'acceso-parte-'))
  prevDataDir = process.env.DATA_DIR
  process.env.DATA_DIR = dir
  await ensureSeeded()
})

afterAll(() => {
  if (prevDataDir === undefined) delete process.env.DATA_DIR
  else process.env.DATA_DIR = prevDataDir
  rmSync(dir, { recursive: true, force: true })
})

const CLAVE = claveDePrueba()

let prevPassword: string | undefined

beforeEach(() => {
  prevPassword = process.env.PROBLEMATICAS_ACCESO_PASSWORD
  process.env.PROBLEMATICAS_ACCESO_PASSWORD = CLAVE
  getSessionUserMock.mockReset()
  getSessionUserMock.mockResolvedValue(null)
  cookiesGetMock.mockReset()
  cookiesGetMock.mockReturnValue(undefined)
})

afterEach(() => {
  if (prevPassword === undefined) delete process.env.PROBLEMATICAS_ACCESO_PASSWORD
  else process.env.PROBLEMATICAS_ACCESO_PASSWORD = prevPassword
})

function usuario(role: string, banned = false) {
  return { id: 'u1', role, banned, nivelIds: [] }
}

function requestConCookie(valor?: string) {
  return new Request('https://ejemplo.test/api', {
    headers: valor ? { cookie: `${NOMBRE_COOKIE}=${valor}` } : {},
  })
}

describe('tieneAccesoAlParte (Route Handlers)', () => {
  it('deja pasar con la contraseña del recorrido público', async () => {
    const { token } = crearTokenSesion()
    await expect(tieneAccesoAlParte(requestConCookie(token))).resolves.toBe(true)
  })

  it('no resuelve la sesión cuando la contraseña ya alcanzó', async () => {
    const { token } = crearTokenSesion()
    await tieneAccesoAlParte(requestConCookie(token))
    expect(getSessionUserMock).not.toHaveBeenCalled()
  })

  it('deja pasar a un administrador sin contraseña', async () => {
    getSessionUserMock.mockResolvedValue(usuario('admin'))
    await expect(tieneAccesoAlParte(requestConCookie())).resolves.toBe(true)
  })

  // 'editor' queda afuera a propósito: la contraseña existe porque el contexto
  // del parte incluye identidad de alumnos, y permiso-nominal.ts ya excluye a
  // ese rol de ese mismo dato.
  it('rechaza a un editor sin contraseña', async () => {
    getSessionUserMock.mockResolvedValue(usuario('editor'))
    await expect(tieneAccesoAlParte(requestConCookie())).resolves.toBe(false)
  })

  it('rechaza a un usuario de consulta sin contraseña', async () => {
    getSessionUserMock.mockResolvedValue(usuario('consulta'))
    await expect(tieneAccesoAlParte(requestConCookie())).resolves.toBe(false)
  })

  it('rechaza a un administrador baneado', async () => {
    getSessionUserMock.mockResolvedValue(usuario('admin', true))
    await expect(tieneAccesoAlParte(requestConCookie())).resolves.toBe(false)
  })

  it('rechaza sin contraseña y sin sesión', async () => {
    await expect(tieneAccesoAlParte(requestConCookie())).resolves.toBe(false)
  })

  it('rechaza una cookie de acceso manipulada', async () => {
    getSessionUserMock.mockResolvedValue(null)
    await expect(tieneAccesoAlParte(requestConCookie('no-es-un-token'))).resolves.toBe(false)
  })
})

describe('tieneAccesoAlParteDesdeCookies (páginas)', () => {
  it('deja pasar con la contraseña del recorrido público', async () => {
    const { token } = crearTokenSesion()
    cookiesGetMock.mockReturnValue({ value: token })
    await expect(tieneAccesoAlParteDesdeCookies()).resolves.toBe(true)
  })

  it('deja pasar a un administrador sin contraseña', async () => {
    getSessionUserMock.mockResolvedValue(usuario('admin'))
    await expect(tieneAccesoAlParteDesdeCookies()).resolves.toBe(true)
  })

  it('rechaza a un editor sin contraseña', async () => {
    getSessionUserMock.mockResolvedValue(usuario('editor'))
    await expect(tieneAccesoAlParteDesdeCookies()).resolves.toBe(false)
  })

  it('rechaza sin contraseña y sin sesión', async () => {
    await expect(tieneAccesoAlParteDesdeCookies()).resolves.toBe(false)
  })
})

// CUE único por test: infra_parte tiene índice único (cueAnexo, periodoId) y
// todos los tests comparten el período sembrado.
let contadorCue = 0
function cueUnico(): string {
  contadorCue += 1
  return `1801604-${String(contadorCue).padStart(3, '0')}`
}

// Construye una verificación pendiente real y la cookie que emitiría el canje
// del token, para ejercitar el re-chequeo contra la fila sin pasar por la
// ruta HTTP.
async function verificacionConSesion() {
  const episodio = await crearEpisodio({
    periodoId: PERIODO_ENOS_2026_2027_ID,
    nombre: 'Episodio de prueba',
  })
  const creada = await crearVerificacion({
    episodioId: episodio.id,
    cueAnexo: cueUnico(),
    solicitadaPorUserId: 'user-director',
  })
  if (!creada.ok) throw new Error(`no se pudo crear la verificación: ${creada.motivo}`)
  const { valorCookie } = crearSesionVerificacion(
    creada.verificacion.id,
    creada.verificacion.cueAnexo,
  )
  return {
    token: creada.token,
    verificacion: creada.verificacion,
    cueAnexo: creada.verificacion.cueAnexo,
    valorCookie,
  }
}

function requestConSesionVerificacion(valorCookie: string) {
  return new Request('https://ejemplo.test/api', {
    headers: { cookie: `${NOMBRE_COOKIE_SESION_VERIFICACION}=${valorCookie}` },
  })
}

describe('tieneAccesoAlParteParaCue (re-chequeo de la fila)', () => {
  it('sesión canjeada de una verificación pendiente: true', async () => {
    const { cueAnexo, valorCookie } = await verificacionConSesion()
    await expect(
      tieneAccesoAlParteParaCue(requestConSesionVerificacion(valorCookie), cueAnexo),
    ).resolves.toBe(true)
  })

  // Regla de N1: la MISMA cookie deja de servir apenas la fila cambia de estado.
  it('la misma sesión con la verificación cancelada: false', async () => {
    const { cueAnexo, valorCookie, verificacion } = await verificacionConSesion()
    await cancelarVerificacion({ verificacionId: verificacion.id, actorUserId: 'user-admin' })

    await expect(
      tieneAccesoAlParteParaCue(requestConSesionVerificacion(valorCookie), cueAnexo),
    ).resolves.toBe(false)
  })

  it('la misma sesión con el token revocado: false', async () => {
    const { cueAnexo, valorCookie, verificacion } = await verificacionConSesion()
    await getDb()
      .update(infraVerificacion)
      .set({ tokenRevocadoEn: new Date().toISOString() })
      .where(eq(infraVerificacion.id, verificacion.id))

    await expect(
      tieneAccesoAlParteParaCue(requestConSesionVerificacion(valorCookie), cueAnexo),
    ).resolves.toBe(false)
  })

  it('la misma sesión con la verificación respondida: false', async () => {
    const { cueAnexo, valorCookie, token, verificacion } = await verificacionConSesion()
    const respuesta = await responderPorEnlace({
      verificacionId: verificacion.id,
      token,
      resultado: 'sin_afectacion',
    })
    expect(respuesta.ok).toBe(true)

    await expect(
      tieneAccesoAlParteParaCue(requestConSesionVerificacion(valorCookie), cueAnexo),
    ).resolves.toBe(false)
  })

  // Regresión: el atajo de la contraseña compartida sigue funcionando sin
  // mirar la base de verificaciones.
  it('la contraseña compartida sigue dando true sin sesión de verificación', async () => {
    const { token } = crearTokenSesion()
    await expect(
      tieneAccesoAlParteParaCue(requestConCookie(token), '140000000'),
    ).resolves.toBe(true)
  })

  // Regresión: un admin sigue entrando sin sesión de verificación.
  it('un administrador sigue dando true sin sesión de verificación', async () => {
    getSessionUserMock.mockResolvedValue(usuario('admin'))
    await expect(
      tieneAccesoAlParteParaCue(requestConCookie(), '140000000'),
    ).resolves.toBe(true)
  })
})

// Misma lógica de re-chequeo, sólo cambia de dónde lee la cookie: un
// subconjunto alcanza (pendiente → true, cancelada → false, regresión admin).
describe('tieneAccesoAlParteParaCueDesdeCookies (re-chequeo, subconjunto)', () => {
  it('sesión canjeada de una verificación pendiente: true', async () => {
    const { cueAnexo, valorCookie } = await verificacionConSesion()
    cookiesGetMock.mockImplementation((nombre: string) =>
      nombre === NOMBRE_COOKIE_SESION_VERIFICACION ? { value: valorCookie } : undefined,
    )

    await expect(tieneAccesoAlParteParaCueDesdeCookies(cueAnexo)).resolves.toBe(true)
  })

  it('la misma sesión con la verificación cancelada: false', async () => {
    const { cueAnexo, valorCookie, verificacion } = await verificacionConSesion()
    await cancelarVerificacion({ verificacionId: verificacion.id, actorUserId: 'user-admin' })
    cookiesGetMock.mockImplementation((nombre: string) =>
      nombre === NOMBRE_COOKIE_SESION_VERIFICACION ? { value: valorCookie } : undefined,
    )

    await expect(tieneAccesoAlParteParaCueDesdeCookies(cueAnexo)).resolves.toBe(false)
  })

  it('un administrador sigue dando true sin sesión de verificación', async () => {
    getSessionUserMock.mockResolvedValue(usuario('admin'))
    await expect(tieneAccesoAlParteParaCueDesdeCookies('140000000')).resolves.toBe(true)
  })
})

import { createHmac, timingSafeEqual } from 'node:crypto'

// Sesión acotada por CUE, canjeada de la credencial de verificación (batch E1
// del protocolo ENOS). Un director que entra por el enlace de "Hay afectación"
// puede usar el formulario de parte SIN la contraseña compartida, pero SÓLO
// para el CUE exacto de la verificación de la que canjeó, y sólo mientras esta
// sesión no venció.
//
// Por qué una cookie distinta y no reusar la de acceso público: la de acceso
// público prueba "alguien conoce la contraseña compartida" y sirve para todo
// el recorrido; ésta prueba "el servidor emitió esta sesión para ESTE CUE tras
// canjear un token válido". Propósito, payload y cookie distintos. Comparten la
// env var como secreto HMAC porque es un secreto de servidor ya configurado,
// no una credencial de usuario; firmar dos payloads distintos con la misma
// clave no mezcla las sesiones (una firma no es válida para el otro formato).
//
// Alcance: nunca lista ni abre partes de otro CUE, nunca otorga rol admin, ni
// se amplía a ningún otro alcance. La comparación de CUE es parte de la
// validación, no un filtro posterior.

export const NOMBRE_COOKIE_SESION_VERIFICACION = 'verificacion_sesion'
const DURACION_SESION_MS = 1000 * 60 * 30 // 30 minutos

// Duplicada a propósito desde acceso-publico.ts, que la mantiene privada: ese
// archivo se declara la única costura con el mundo público y no exporta sus
// helpers. Importarla acá acoplaría este módulo a su implementación interna;
// mismo criterio que ya usa acceso-parte.ts para no acoplarse.
function obtenerSecreto(): string {
  const secreto = process.env.PROBLEMATICAS_ACCESO_PASSWORD
  if (!secreto) {
    throw new Error('PROBLEMATICAS_ACCESO_PASSWORD no está configurada')
  }
  return secreto
}

function firmar(payload: string, secreto: string): string {
  return createHmac('sha256', secreto).update(payload).digest('base64url')
}

// Comparación en tiempo constante. Nunca uses === contra la firma: filtraría
// por timing dónde difieren.
function iguales(a: string, b: string): boolean {
  const bufA = Buffer.from(a)
  const bufB = Buffer.from(b)
  if (bufA.length !== bufB.length) {
    // Igual comparamos algo del mismo largo que a, para no salir antes y no
    // filtrar por timing que las longitudes no coinciden.
    timingSafeEqual(bufA, bufA)
    return false
  }
  return timingSafeEqual(bufA, bufB)
}

// Token de sesión acotada: "verificacionId|cueAnexo|expiración.firma". Se usa
// `|` como separador porque ni verificacionId (uuid) ni cueAnexo (dígitos) lo
// contienen. La firma prueba que el servidor emitió esta sesión; el CUE dentro
// del payload es lo que acota el acceso.
export function crearSesionVerificacion(
  verificacionId: string,
  cueAnexo: string,
  ahora: Date = new Date(),
): { valorCookie: string; expiraEn: Date } {
  const expiraEn = new Date(ahora.getTime() + DURACION_SESION_MS)
  const payload = `${verificacionId}|${cueAnexo}|${expiraEn.getTime()}`
  const firma = firmar(payload, obtenerSecreto())
  return { valorCookie: `${payload}.${firma}`, expiraEn }
}

type SesionVerificada = { verificacionId: string; cueAnexo: string; expiraEnMs: number }

// Parseo + verificación de firma + expiración de la COOKIE (no de la
// verificación en la base: eso lo re-chequea el llamador contra la fila real,
// ver acceso-parte.ts). Devuelve null ante cualquier fallo de forma, firma o
// vencimiento — nunca lanza.
function verificarSesion(
  valorCookie: string | undefined | null,
  ahora: Date,
): SesionVerificada | null {
  if (!valorCookie) return null
  const separador = valorCookie.indexOf('.')
  if (separador < 0) return null
  const payload = valorCookie.slice(0, separador)
  const firma = valorCookie.slice(separador + 1)
  if (!payload || !firma) return null

  let secreto: string
  try {
    secreto = obtenerSecreto()
  } catch {
    return null
  }
  const firmaEsperada = firmar(payload, secreto)
  if (!iguales(firma, firmaEsperada)) return null

  const [verificacionId, cueAnexoDelToken, expiraEnMsStr] = payload.split('|')
  if (!verificacionId || !cueAnexoDelToken || !expiraEnMsStr) return null

  const expiraEnMs = Number(expiraEnMsStr)
  if (!Number.isFinite(expiraEnMs) || expiraEnMs <= ahora.getTime()) return null

  return { verificacionId, cueAnexo: cueAnexoDelToken, expiraEnMs }
}

export function sesionVerificacionValidaParaCue(
  valorCookie: string | undefined | null,
  cueAnexo: string,
  ahora: Date = new Date(),
): boolean {
  const sesion = verificarSesion(valorCookie, ahora)
  // El CUE pedido tiene que ser el de esta sesión: el acceso nunca se amplía.
  return sesion !== null && sesion.cueAnexo === cueAnexo
}

// Igual que sesionVerificacionValidaParaCue, pero devuelve el verificacionId
// de la sesión en vez de un booleano cuando la cookie es válida PARA ESE CUE
// (firma correcta, CUE coincide, cookie no vencida). Quien llame TODAVÍA debe
// re-chequear la fila de la verificación en la base (estado, revocación,
// vencimiento del token) antes de conceder acceso — esta función sólo prueba
// que la cookie en sí es auténtica y no vencida, no que la verificación siga
// habilitando escritura.
export function verificacionIdDeSesionValida(
  valorCookie: string | undefined | null,
  cueAnexo: string,
  ahora: Date = new Date(),
): string | null {
  const sesion = verificarSesion(valorCookie, ahora)
  if (!sesion || sesion.cueAnexo !== cueAnexo) return null
  return sesion.verificacionId
}

// Opciones para setear la cookie al canjear el token. secure sólo en
// producción para no romper el desarrollo local sobre HTTP.
export function opcionesCookieSesionVerificacion(expiraEn: Date) {
  return {
    httpOnly: true as const,
    sameSite: 'lax' as const,
    secure: process.env.NODE_ENV === 'production',
    expires: expiraEn,
    path: '/',
  }
}

export function extraerCookieVerificacionSesion(
  cookieHeader: string | null | undefined,
): string | undefined {
  if (!cookieHeader) return undefined
  for (const parte of cookieHeader.split(';')) {
    const igual = parte.indexOf('=')
    if (igual < 0) continue
    const clave = parte.slice(0, igual).trim()
    if (clave === NOMBRE_COOKIE_SESION_VERIFICACION) {
      return decodeURIComponent(parte.slice(igual + 1).trim())
    }
  }
  return undefined
}

// Máquina de estados de las verificaciones del batch E1 del protocolo ENOS.
// Una verificación es un pedido de confirmación a un establecimiento: nace
// 'pendiente' con una credencial de un solo uso (enlace público) y termina
// 'respondida' o 'cancelada'. Ver lib/db/schema.ts (infraVerificacion /
// infraVerificacionEvento) para el modelo y verificacion-token.ts para la
// credencial.
//
// Regla transversal: TODA transición de estado usa un UPDATE condicionado con
// `.returning()` (mismo patrón que lib/infraestructura/riesgo/job-run.ts).
// Nunca un select-then-act separado: entre el read y el write otra request
// concurrente puede cancelar o responder, y el WHERE es lo único que garantiza
// que gane una sola. El select posterior al UPDATE fallido sirve para
// *clasificar* el conflicto (404/409), no para decidir la escritura.
import { randomUUID } from 'node:crypto'
import { and, desc, eq, isNull, sql } from 'drizzle-orm'
import { getDb } from '@/lib/db'
import {
  infraAfectacion,
  infraMovimiento,
  infraParte,
  infraVerificacion,
  infraVerificacionEvento,
} from '@/lib/db/schema'
import { obtenerEpisodio } from '@/lib/infraestructura/episodios'
import {
  calcularVencimientoToken,
  generarToken,
  hashearToken,
  tokenExpirado,
} from './verificacion-token'

export type VerificacionRow = typeof infraVerificacion.$inferSelect

export type ResultadoTransicion =
  | { ok: true; verificacion: VerificacionRow; replay?: boolean }
  | { ok: false; status: 403 | 404 | 409 | 410; motivo: string }

type ResultadoRespuesta = 'sin_afectacion' | 'con_afectacion' | 'no_disponible'
type CanalRespuesta = 'enlace' | 'telefono' | 'whatsapp' | 'presencial' | 'otro'
type CanalAsistido = 'telefono' | 'whatsapp' | 'presencial' | 'otro'

type OrigenRespuesta =
  | { tipo: 'enlace'; token: string }
  | { tipo: 'asistida'; actorUserId: string; canal: CanalAsistido }

type CrearVerificacionInput = {
  episodioId: string
  cueAnexo: string
  solicitadaPorUserId: string
  vencimientoEn?: string | null
}

type CancelarVerificacionInput = {
  verificacionId: string
  actorUserId: string
  motivo?: string | null
}

type ResponderPorEnlaceInput = {
  verificacionId: string
  token: string
  resultado: ResultadoRespuesta
  movimientoId?: string | null
}

type ResponderAsistidaInput = {
  verificacionId: string
  actorUserId: string
  canal: CanalAsistido
  resultado: ResultadoRespuesta
  movimientoId?: string | null
}

// Emite un pedido de verificación. El `token` en claro viaja en la respuesta
// SÓLO acá: es el único momento en que existe fuera del proceso. La base
// guarda nada más que su sha256 (`tokenHash`), así que después de esta llamada
// no hay forma de recuperarlo — quien lo perdió tiene que pedir otro pedido.
//
// No reemplaza verificaciones anteriores del mismo CUE: una nueva solicitud
// convive con las previas (spec E1). Si el episodio no está abierto no se
// emiten pedidos.
export async function crearVerificacion(
  input: CrearVerificacionInput,
  ahora: Date = new Date(),
): Promise<
  | { ok: true; verificacion: VerificacionRow; token: string }
  | { ok: false; status: 404 | 409; motivo: 'episodio_no_existe' | 'episodio_cerrado' }
> {
  const db = getDb()
  const episodio = await obtenerEpisodio(input.episodioId)
  if (!episodio) return { ok: false, status: 404, motivo: 'episodio_no_existe' }
  if (episodio.estado !== 'abierto') return { ok: false, status: 409, motivo: 'episodio_cerrado' }

  const { token, tokenHash } = generarToken()
  const ahoraIso = ahora.toISOString()

  const [verificacion] = await db
    .insert(infraVerificacion)
    .values({
      id: randomUUID(),
      episodioId: input.episodioId,
      cueAnexo: input.cueAnexo,
      estado: 'pendiente',
      solicitadaEn: ahoraIso,
      solicitadaPorUserId: input.solicitadaPorUserId,
      vencimientoEn: input.vencimientoEn ?? null,
      resultado: null,
      discrepancia: 0,
      respondidaEn: null,
      respondidaCanal: null,
      respondidaPorUserId: null,
      movimientoId: null,
      canceladaEn: null,
      canceladaPorUserId: null,
      motivoCancelacion: null,
      tokenHash,
      // Vencimiento de la credencial (bloquea, 410), no el SLA informativo.
      tokenExpiraEn: calcularVencimientoToken(ahora),
      tokenRevocadoEn: null,
      tokenConsumidoEn: null,
      creadaEn: ahoraIso,
      actualizadaEn: ahoraIso,
    })
    .returning()

  await db.insert(infraVerificacionEvento).values({
    id: randomUUID(),
    verificacionId: verificacion.id,
    tipo: 'creada',
    actorTipo: 'usuario',
    actorUserId: input.solicitadaPorUserId,
    canal: null,
    motivo: null,
    correlacionId: null,
    creadaEn: ahoraIso,
  })

  return { ok: true, verificacion, token }
}

// Cancela un pedido pendiente. El UPDATE condicionado a estado='pendiente' es
// el árbitro de la carrera cancelar/responder: gana quien logre el UPDATE
// primero. El perdedor cae en el select de clasificación y recibe el estado
// real ya persistido, no una suposición.
export async function cancelarVerificacion(
  input: CancelarVerificacionInput,
  ahora: Date = new Date(),
): Promise<ResultadoTransicion> {
  const db = getDb()
  const ahoraIso = ahora.toISOString()

  const [actualizada] = await db
    .update(infraVerificacion)
    .set({
      estado: 'cancelada',
      canceladaEn: ahoraIso,
      canceladaPorUserId: input.actorUserId,
      motivoCancelacion: input.motivo ?? null,
      actualizadaEn: ahoraIso,
    })
    .where(
      and(
        eq(infraVerificacion.id, input.verificacionId),
        eq(infraVerificacion.estado, 'pendiente'),
      ),
    )
    .returning()

  if (actualizada) {
    await db.insert(infraVerificacionEvento).values({
      id: randomUUID(),
      verificacionId: input.verificacionId,
      tipo: 'cancelada',
      actorTipo: 'usuario',
      actorUserId: input.actorUserId,
      canal: null,
      motivo: input.motivo ?? null,
      correlacionId: null,
      creadaEn: ahoraIso,
    })
    return { ok: true, verificacion: actualizada }
  }

  // El UPDATE no matcheó: la fila no existe, ya estaba cancelada o ya se
  // respondió. El select sólo clasifica el motivo.
  const [fila] = await db
    .select()
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, input.verificacionId))
  if (!fila) return { ok: false, status: 404, motivo: 'no_existe' }
  if (fila.estado === 'cancelada') return { ok: false, status: 409, motivo: 'ya_cancelada' }
  if (fila.estado === 'respondida') return { ok: false, status: 409, motivo: 'ya_respondida' }
  return { ok: false, status: 409, motivo: fila.estado }
}

// true si existe al menos una afectación vigente (retirada_en IS NULL) para
// ese establecimiento dentro del período. Es la señal que convierte una
// respuesta 'sin_afectacion' en discrepancia: el director dice que no pasa
// nada mientras el parte registra lo contrario.
async function existeAfectacionVigente(cueAnexo: string, periodoId: string): Promise<boolean> {
  const db = getDb()
  const [fila] = await db
    .select({ uno: sql<number>`1` })
    .from(infraAfectacion)
    .innerJoin(infraParte, eq(infraAfectacion.parteId, infraParte.id))
    .where(
      and(
        eq(infraParte.cueAnexo, cueAnexo),
        eq(infraParte.periodoId, periodoId),
        isNull(infraAfectacion.retiradaEn),
      ),
    )
    .limit(1)
  return Boolean(fila)
}

// Defensa contra vínculo cruzado entre escuelas: un movimientoId sólo es
// válido para ESTA verificación si el parte al que pertenece es del mismo
// cueAnexo. Sin este chequeo, cualquier movimientoId ajeno (de otro CUE)
// quedaría enlazado igual — un bug real encontrado por revisión adversarial.
async function movimientoPerteneceAlCue(movimientoId: string, cueAnexo: string): Promise<boolean> {
  const db = getDb()
  const [fila] = await db
    .select({ cueAnexo: infraParte.cueAnexo })
    .from(infraMovimiento)
    .innerJoin(infraParte, eq(infraMovimiento.parteId, infraParte.id))
    .where(eq(infraMovimiento.id, movimientoId))
    .limit(1)
  return fila?.cueAnexo === cueAnexo
}

async function insertarEvento(params: {
  verificacionId: string
  tipo: 'respondida' | 'discrepancia_detectada'
  origen: OrigenRespuesta
  canal: CanalRespuesta
  ahoraIso: string
}): Promise<void> {
  const db = getDb()
  await db.insert(infraVerificacionEvento).values({
    id: randomUUID(),
    verificacionId: params.verificacionId,
    tipo: params.tipo,
    actorTipo: params.origen.tipo === 'enlace' ? 'enlace' : 'usuario',
    actorUserId: params.origen.tipo === 'asistida' ? params.origen.actorUserId : null,
    canal: params.canal,
    motivo: null,
    correlacionId: null,
    creadaEn: params.ahoraIso,
  })
}

// Núcleo compartido por las dos vías de respuesta (enlace público y carga
// asistida por staff). Parametrizado por origen para que la validación de la
// credencial y la atribución de la auditoría vivan en un solo lugar.
//
// Orden deliberado de los chequeos:
//   1. credencial (sólo enlace) ANTES del estado: una credencial inválida
//      nunca debe revelar si la solicitud existe, está cancelada o ya se
//      respondió. Mismo criterio para 403 y para los 410.
//   2. estado persistido, para resolver cancelación y replay idempotente.
//   3. escritura atómica condicionada, con un único reintento si perdió una
//      carrera contra una transición concurrente.
async function transicionarARespondida(
  verificacionId: string,
  resultado: ResultadoRespuesta,
  origen: OrigenRespuesta,
  movimientoId: string | null,
  ahora: Date,
): Promise<ResultadoTransicion> {
  const db = getDb()
  const ahoraIso = ahora.toISOString()
  const canal: CanalRespuesta = origen.tipo === 'enlace' ? 'enlace' : origen.canal

  // Máximo un reintento: si tras re-leer el estado volvemos a perder el
  // UPDATE condicionado, hay una tormenta de transiciones concurrentes que no
  // vale la pena seguir persiguiendo. El diseño congela "una vez más".
  for (let intento = 0; intento < 2; intento += 1) {
    const [fila] = await db
      .select()
      .from(infraVerificacion)
      .where(eq(infraVerificacion.id, verificacionId))
    if (!fila) return { ok: false, status: 404, motivo: 'no_existe' }

    if (origen.tipo === 'enlace') {
      if (hashearToken(origen.token) !== fila.tokenHash) {
        return { ok: false, status: 403, motivo: 'credencial_invalida' }
      }
      if (fila.tokenRevocadoEn !== null) {
        return { ok: false, status: 410, motivo: 'credencial_revocada' }
      }
      if (tokenExpirado(fila.tokenExpiraEn, ahora)) {
        return { ok: false, status: 410, motivo: 'credencial_vencida' }
      }
    }

    if (fila.estado === 'cancelada') {
      return { ok: false, status: 409, motivo: 'solicitud_cancelada' }
    }

    if (fila.estado === 'respondida') {
      // Retry idéntico: idempotente, no escribe un segundo evento. Un retry
      // con otra respuesta es un conflicto real del usuario, no un reintento.
      if (fila.resultado === resultado) return { ok: true, verificacion: fila, replay: true }
      return { ok: false, status: 409, motivo: 'respuesta_contradictoria' }
    }

    // fila.estado === 'pendiente': calcular discrepancia y escribir. La
    // consulta de afectación vigente usa el período del episodio, que es el
    // que ancla el parte del establecimiento.
    const episodio = await obtenerEpisodio(fila.episodioId)
    const hayAfectacion = episodio
      ? await existeAfectacionVigente(fila.cueAnexo, episodio.periodoId)
      : false
    const discrepancia = resultado === 'sin_afectacion' && hayAfectacion ? 1 : 0

    if (resultado === 'con_afectacion' && movimientoId !== null) {
      if (!(await movimientoPerteneceAlCue(movimientoId, fila.cueAnexo))) {
        return { ok: false, status: 409, motivo: 'movimiento_cue_no_coincide' }
      }
    }

    const [actualizada] = await db
      .update(infraVerificacion)
      .set({
        estado: 'respondida',
        resultado,
        respondidaEn: ahoraIso,
        respondidaCanal: canal,
        respondidaPorUserId: origen.tipo === 'asistida' ? origen.actorUserId : null,
        movimientoId,
        discrepancia,
        // La credencial se consume sólo cuando la respuesta vino por enlace.
        // La vía asistida no toca tokenConsumidoEn: el enlace sigue válido si
        // el director todavía no lo usó.
        tokenConsumidoEn: origen.tipo === 'enlace' ? ahoraIso : fila.tokenConsumidoEn,
        actualizadaEn: ahoraIso,
      })
      .where(
        and(
          eq(infraVerificacion.id, verificacionId),
          eq(infraVerificacion.estado, 'pendiente'),
        ),
      )
      .returning()

    if (!actualizada) continue // perdió la carrera: re-lee y reintenta una vez

    await insertarEvento({
      verificacionId,
      tipo: 'respondida',
      origen,
      canal,
      ahoraIso,
    })
    if (discrepancia === 1) {
      await insertarEvento({
        verificacionId,
        tipo: 'discrepancia_detectada',
        origen,
        canal,
        ahoraIso,
      })
    }
    return { ok: true, verificacion: actualizada }
  }

  // Se perdió la carrera dos veces seguidas: el estado siguió cambiando bajo
  // los pies. No es un camino alcanzable en operación normal; se informa como
  // conflicto en vez de inventar un resultado.
  return { ok: false, status: 409, motivo: 'conflicto_concurrente' }
}

export async function responderPorEnlace(
  input: ResponderPorEnlaceInput,
  ahora: Date = new Date(),
): Promise<ResultadoTransicion> {
  // Error de programación del caller, no un caso de usuario: una respuesta
  // 'con_afectacion' sin movimiento es un dato incompleto que no debe
  // persistirse.
  if (input.resultado === 'con_afectacion' && !input.movimientoId) {
    throw new Error('con_afectacion requiere movimientoId')
  }
  return transicionarARespondida(
    input.verificacionId,
    input.resultado,
    { tipo: 'enlace', token: input.token },
    input.movimientoId ?? null,
    ahora,
  )
}

export async function responderAsistida(
  input: ResponderAsistidaInput,
  ahora: Date = new Date(),
): Promise<ResultadoTransicion> {
  if (input.resultado === 'con_afectacion' && !input.movimientoId) {
    throw new Error('con_afectacion requiere movimientoId')
  }
  return transicionarARespondida(
    input.verificacionId,
    input.resultado,
    { tipo: 'asistida', actorUserId: input.actorUserId, canal: input.canal },
    input.movimientoId ?? null,
    ahora,
  )
}

// Chequeo de SÓLO LECTURA para que la página pública muestre el estado antes
// de que el director elija una respuesta. No escribe, no consume el token y no
// valida contra un resultado (todavía no hay uno). Misma secuencia de
// validación de credencial que transicionarARespondida, sin el paso de
// escritura. Si ya está respondida se devuelve igual como ok: la página
// necesita poder mostrar el resultado final, no ocultarlo.
export async function validarCredencial(
  input: { verificacionId: string; token: string },
  ahora: Date = new Date(),
): Promise<
  | { ok: true; verificacion: VerificacionRow }
  | { ok: false; status: 403 | 404 | 409 | 410; motivo: string }
> {
  const db = getDb()
  const [fila] = await db
    .select()
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, input.verificacionId))
  if (!fila) return { ok: false, status: 404, motivo: 'no_existe' }

  if (hashearToken(input.token) !== fila.tokenHash) {
    return { ok: false, status: 403, motivo: 'credencial_invalida' }
  }
  if (fila.tokenRevocadoEn !== null) {
    return { ok: false, status: 410, motivo: 'credencial_revocada' }
  }
  if (tokenExpirado(fila.tokenExpiraEn, ahora)) {
    return { ok: false, status: 410, motivo: 'credencial_vencida' }
  }
  if (fila.estado === 'cancelada') {
    return { ok: false, status: 409, motivo: 'solicitud_cancelada' }
  }
  return { ok: true, verificacion: fila }
}

// Regla de N1 (gate del batch E1): la sesión derivada del token nunca puede
// ser más fuerte que el token. Esta función es el único lugar que decide si
// una verificación sigue habilitando ESCRITURA: se usa tanto al canjear una
// sesión nueva (canjear-sesion) como en CADA request que reusa una sesión ya
// emitida (tieneAccesoAlParteParaCue en acceso-parte.ts) — nunca basta con
// que la cookie tenga firma/expiración válidas, la fila real de la
// verificación manda siempre.
export async function verificacionHabilitaSesionEscritura(
  verificacionId: string,
  ahora: Date = new Date(),
): Promise<boolean> {
  const fila = await obtenerVerificacion(verificacionId)
  if (!fila) return false
  if (fila.estado !== 'pendiente') return false
  if (fila.tokenConsumidoEn !== null) return false
  if (fila.tokenRevocadoEn !== null) return false
  if (tokenExpirado(fila.tokenExpiraEn, ahora)) return false
  return true
}

export async function obtenerVerificacion(
  verificacionId: string,
): Promise<VerificacionRow | null> {
  const db = getDb()
  const [fila] = await db
    .select()
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, verificacionId))
  return fila ?? null
}

export async function listarVerificaciones(
  input?: { episodioId?: string; cueAnexo?: string; estado?: 'pendiente' | 'respondida' | 'cancelada' },
): Promise<VerificacionRow[]> {
  const db = getDb()
  const condiciones = []
  if (input?.episodioId) condiciones.push(eq(infraVerificacion.episodioId, input.episodioId))
  if (input?.cueAnexo) condiciones.push(eq(infraVerificacion.cueAnexo, input.cueAnexo))
  if (input?.estado) condiciones.push(eq(infraVerificacion.estado, input.estado))

  const base = db.select().from(infraVerificacion)
  const conFiltro = condiciones.length > 0 ? base.where(and(...condiciones)) : base
  return conFiltro.orderBy(desc(infraVerificacion.solicitadaEn))
}

// Auditoría de un intento de vínculo fallido (batch E1): quien llama a esto ya
// tiene un movimiento real guardado (el parte del director se guardó bien) y
// el vínculo con la verificación de origen no prendió por el motivo que sea
// (credencial inválida/vencida/revocada, respuesta contradictoria, etc.). Esto
// NO reintenta la transición ni toca `estado`/`resultado`/`movimientoId` de la
// verificación: sólo dejar un rastro append-only para que el operador vea que
// hubo un intento de responder con afectación que no quedó enlazado. Si el id
// de verificación ni siquiera existe (token completamente ajeno/inventado), no
// hay nada real que auditar: no se escribe nada y se devuelve false.
export async function registrarIntentoVinculoFallido(
  input: { verificacionId: string; motivo: string },
  ahora: Date = new Date(),
): Promise<boolean> {
  const db = getDb()
  const [fila] = await db
    .select({ id: infraVerificacion.id })
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, input.verificacionId))
  if (!fila) return false

  await db.insert(infraVerificacionEvento).values({
    id: randomUUID(),
    verificacionId: input.verificacionId,
    tipo: 'vinculo_fallido',
    actorTipo: 'sistema',
    actorUserId: null,
    canal: null,
    motivo: input.motivo,
    correlacionId: null,
    creadaEn: ahora.toISOString(),
  })
  return true
}

