let seedPromise: Promise<void> | null = null

export function ensureSeeded() {
  if (!seedPromise) {
    seedPromise = seedHub().catch((err) => {
      seedPromise = null
      throw err
    })
  }
  return seedPromise
}

function withSeedFile(r: Recurso): Recurso {
  const spec = SEED_PUBLIC_FILES.find((s) => s.id === r.id)
  if (!spec) return r
  const copied = copySeedPublicFile(spec)
  return {
    ...r,
    ruta: undefined,
    storageKey: copied.storageKey,
    mime: spec.mime,
    nombreOriginal: spec.nombreOriginal,
    size: copied.size,
  }
}

async function convertExistingSeedFiles() {
  const db = getDb()
  const rows = await db
    .select({
      id: recursos.id,
      ruta: recursos.ruta,
      storageKey: recursos.storageKey,
    })
    .from(recursos)
  for (const row of rows) {
    if (!shouldReplaceWithSeedFile(row)) continue
    const spec = SEED_PUBLIC_FILES.find((s) => s.id === row.id)
    if (!spec) continue
    const copied = copySeedPublicFile(spec)
    await db
      .update(recursos)
      .set({
        ruta: null,
        storageKey: copied.storageKey,
        mime: spec.mime,
        nombreOriginal: spec.nombreOriginal,
        size: copied.size,
      })
      .where(eq(recursos.id, row.id))
  }
}

// `infra_movimiento.idempotency_key` no existía en el batch de esquema
// (batch 1): parteActualizacionInputSchema exige `idempotencyKey` pero la
// tabla no tenía dónde guardarla. Mismo motivo que cualquier columna
// agregada con ALTER a una base poblada: ALTER TABLE ADD COLUMN no es
// idempotente y SQLite no permite agregar una columna NOT NULL a una tabla
// con filas, así que queda nullable. El índice único de HUB_DDL ya cubre las
// bases nuevas; acá sólo hace falta la columna para las que ya tenían la
// tabla creada sin ella.
export async function ensureMovimientoIdempotencyKeyColumn(): Promise<void> {
  const db = getDb()
  const info = await db.$client.execute("PRAGMA table_info('infra_movimiento')")
  const tieneColumna = info.rows.some((r) => String(r.name) === 'idempotency_key')
  if (!tieneColumna) {
    await db.$client.execute('ALTER TABLE infra_movimiento ADD COLUMN idempotency_key text')
  }
  await db.$client.execute(
    'CREATE UNIQUE INDEX IF NOT EXISTS `infra_movimiento_idempotency_key_uidx` ON `infra_movimiento` (`idempotency_key`)',
  )
}

// `infra_movimiento.episodio_id` llega con el batch E1 (episodios): enlaza el
// movimiento con el episodio que lo originó. Mismo motivo que idempotencyKey
// para quedar nullable y agregarse por ALTER: SQLite no permite agregar una
// columna NOT NULL a una tabla con filas. Sin asignación retroactiva: los
// movimientos históricos quedan en NULL. HUB_DDL ya cubre las bases nuevas;
// acá sólo hace falta la columna para las que ya tenían la tabla sin ella.
export async function ensureMovimientoEpisodioIdColumn(): Promise<void> {
  const db = getDb()
  const info = await db.$client.execute("PRAGMA table_info('infra_movimiento')")
  const tieneColumna = info.rows.some((r) => String(r.name) === 'episodio_id')
  if (!tieneColumna) {
    await db.$client.execute('ALTER TABLE infra_movimiento ADD COLUMN episodio_id text')
  }
}

// infra_acceso_nominal_log.problematica_id nace apuntando al modelo
// deprecado, retirado en la Fase 4; F3.3 la repuntó a infra_afectacion.id. Es texto plano
// SIN foreign key, así que el rename es barato — no hay índices ni
// constraints que reconstruir.
export async function ensureAccesoNominalLogAfectacionIdColumn(): Promise<void> {
  const db = getDb()
  const info = await db.$client.execute("PRAGMA table_info('infra_acceso_nominal_log')")
  const columnas = new Set(info.rows.map((r) => String(r.name)))
  if (columnas.has('afectacion_id')) return
  if (!columnas.has('problematica_id')) return // tabla creada ya con el nombre nuevo (DDL fresco)
  await db.$client.execute('ALTER TABLE infra_acceso_nominal_log RENAME COLUMN problematica_id TO afectacion_id')
}

// Id fijo y estable del único período que existe en esta etapa (protocolo
// ENOS 2026/2027, ver CONTRACT.md del batch de esquema: "la situación
// hidrometeorológica es UN período provincial, no un episodio por
// establecimiento"). No hay ABM de períodos todavía, así que sembrarlo con un
// id conocido evita tener que buscarlo por nombre.
export const PERIODO_ENOS_2026_2027_ID = 'periodo-enos-2026-2027'

// Siembra idempotente (onConflictDoNothing por id) del único período que
// existe en esta etapa (protocolo ENOS 2026/2027). El backfill que enlazaba
// problemáticas del modelo deprecado con partes se retiró en la Fase 4
// (modelo eliminado, datos de prueba sin backfill); el período se conserva
// porque pertenece al modelo de parte vivo: parte-consulta, el mapa y los
// tests lo esperan sembrado por ensureSeeded().
export async function sembrarPeriodoEnos(): Promise<void> {
  const db = getDb()
  await db
    .insert(infraPeriodo)
    .values({
      id: PERIODO_ENOS_2026_2027_ID,
      nombre: 'Protocolo ENOS 2026/2027',
      inicioEn: '2026-01-01T00:00:00.000Z',
      finEn: null,
      estado: 'vigente',
      creadaEn: new Date().toISOString(),
    })
    .onConflictDoNothing()
}

async function seedHub() {
  const db = getDb()
  await db.$client.executeMultiple(HUB_DDL)
  // F4.6: las tres tablas del modelo deprecado ya no se crean en HUB_DDL; se
  // dropean acá, donde antes vivían sus helpers ensure/backfill, para que una
  // base existente se limpie sola al arrancar. Los datos eran de prueba: sin
  // backfill, dropeo directo. IF EXISTS lo hace idempotente y el orden
  // hijos→padre evita violar las FK que apuntaban a la tabla madre.
  await db.$client.execute('DROP TABLE IF EXISTS `infra_problematica_alumno`')
  await db.$client.execute('DROP TABLE IF EXISTS `infra_problematica_seccion`')
  await db.$client.execute('DROP TABLE IF EXISTS `infra_problematica`')
  await ensureMovimientoIdempotencyKeyColumn()
  await ensureMovimientoEpisodioIdColumn()
  await ensureAccesoNominalLogAfectacionIdColumn()

  const [row] = await db.select({ n: count() }).from(niveles)
  if ((row?.n ?? 0) === 0) {
    const seeded = seedRecursos.map(withSeedFile)
    const tagJoins = seeded.flatMap((r) =>
      r.tagIds.map((tagId) => ({ recursoId: r.id, tagId })),
    )

    await db.transaction(async (tx) => {
      await tx.insert(niveles).values(seedNiveles)
      await tx.insert(tipos).values(seedTipos)
      await tx.insert(categorias).values(seedCategorias)
      await tx.insert(tags).values(seedTags)
      await tx.insert(recursos).values(
        seeded.map(
          ({ tagIds: _tagIds, audienciaNivelIds: _n, audienciaUserIds: _u, ...row }) =>
            row,
        ),
      )
      if (tagJoins.length > 0) {
        await tx.insert(recursoTags).values(tagJoins)
      }
    })
  } else {
    await convertExistingSeedFiles()
  }

  // Fuera del if: corre siempre, también sobre una base ya poblada, y nunca
  // toca la audiencia configurada del recurso (ver recurso-seed.ts).
  await upsertRecursoInfraestructura()

  // Motivos de infraestructura: siembra idempotente (onConflictDoNothing,
  // ver sembrarMotivos). Corre siempre, no sólo en la siembra inicial, para
  // cubrir instalaciones ya pobladas que suman esta migración. (El backfill
  // de categoria sobre el modelo deprecado se retiró en la Fase 4.)
  await sembrarMotivos()
  // Debe correr después de sembrar: renombra los comodines heredados y recién
  // ahí crea el índice único sobre `nombre`, que es lo que hace que
  // resolverCategoria pueda deducir la categoría sin ambigüedad.
  await ensureMotivoNombreUnico()

  // Modelo de parte (ver docs/especificacion-funcional-trayectoria-evento-hidrometeorologico.md):
  // siembra el período provincial. Idempotente, corre siempre.
  await sembrarPeriodoEnos()

  // Siembra ge_localizacion desde el JSON versionado si esta vacia: ge.sqlite
  // vive en el volumen y una instalacion nueva arrancaria sin escuelas.
  await ensureLocalizacionesSeeded()

  await seedFirstAdmin()
}

async function seedFirstAdmin() {
  const db = getDb()
  const [row] = await db.select({ n: count() }).from(user)
  if ((row?.n ?? 0) > 0) return

  const email = process.env.ADMIN_EMAIL
  const password = process.env.ADMIN_PASSWORD
  if (!email || !password) {
    console.warn(
      'Skipping first admin seed: ADMIN_EMAIL and ADMIN_PASSWORD are required',
    )
    return
  }

  const { auth } = await import('@/lib/auth')
  const ctx = await auth.$context
  const created = await ctx.internalAdapter.createUser(
    {
      email,
      name: 'Admin',
      role: 'admin',
      emailVerified: true,
    },
    { method: 'admin' },
  )
  await ctx.internalAdapter.createAccount({
    userId: created.id,
    accountId: created.id,
    providerId: 'credential',
    issuer: 'local:credential',
    password: await ctx.password.hash(password),
  })
}

'use client'

import { useState } from 'react'
import type { FormEvent } from 'react'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'

// Pantalla de ingreso para la contraseña temporal de acceso público (ver
// lib/infraestructura/acceso-publico.ts). Simple a propósito: es lo único
// que ve un director sin cuenta antes de llegar al formulario.
export function AccesoForm() {
  const router = useRouter()
  const [password, setPassword] = useState('')
  const [enviando, setEnviando] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function manejarEnvio(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault()
    if (enviando) return
    setEnviando(true)
    setError(null)
    try {
      const respuesta = await fetch('/api/problematicas/acceso', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password }),
      })
      if (!respuesta.ok) {
        const cuerpo = await respuesta.json().catch(() => null)
        setError(cuerpo?.error ?? 'No se pudo verificar la contraseña.')
        setEnviando(false)
        return
      }
      // La cookie de sesión ya quedó seteada por la respuesta; refresh vuelve
      // a renderizar la página del servidor, que ahora la va a encontrar.
      router.refresh()
    } catch {
      setError('No se pudo verificar la contraseña.')
      setEnviando(false)
    }
  }

  return (
    <form className="acceso-form" onSubmit={manejarEnvio}>
      <p className="acceso-form__intro">Este formulario requiere una contraseña de acceso.</p>
      <div className="acceso-form__campo">
        <Label htmlFor="acceso-password">Contraseña</Label>
        <input
          id="acceso-password"
          type="password"
          className="ui-input"
          value={password}
          onChange={(evento) => setPassword(evento.target.value)}
          disabled={enviando}
          autoFocus
        />
      </div>

      {error && (
        <p className="acceso-form__error" role="alert">
          {error}
        </p>
      )}

      <Button type="submit" disabled={enviando || password.length === 0}>
        Ingresar
      </Button>
    </form>
  )
}

'use client'

import { useEffect, useState, type JSX } from 'react'
import { Button } from '@/components/ui/button'
import { EstadoActualAfectacion } from './estado-actual-afectacion'
import {
  ETIQUETA_ESTABLECIMIENTO,
  ETIQUETA_SERVICIO,
  MENSAJE_ACCESO_VENCIDO,
  MENSAJE_ERROR_LECTURA,
  MENSAJE_SIN_CORTE,
  MENSAJE_SIN_SITUACION,
  formatearMomento,
  rigeDesdeDelServicio,
  sinSituacionEnSeguimiento,
  type EstadoActualRespuesta,
} from './estado-actual-textos'

type Estado =
  | { fase: 'cargando' }
  | { fase: 'listo'; datos: EstadoActualRespuesta }
  | { fase: 'error'; mensaje: string; reintentable: boolean }

function enlaceCon(ruta: string, cue: string, foco?: string): string {
  const base = `${ruta}?cue=${encodeURIComponent(cue)}`
  return foco ? `${base}&foco=${foco}` : base
}

// Pide el estado actual y lo traduce a la fase que corresponde. Nunca lanza y
// nunca toca estado de React: así el efecto de abajo sólo tiene que aplicar el
// resultado en un callback, sin encadenar renders.
async function obtenerEstado(cue: string): Promise<Estado> {
  try {
    const respuesta = await fetch(`/api/problematicas/parte?cue=${encodeURIComponent(cue)}`)
    if (!respuesta.ok) {
      // Un acceso vencido no se arregla reintentando: se arregla volviendo a
      // ingresar la contraseña. Ofrecer "Reintentar" ahí sería mentirle al
      // director (Nielsen #9).
      if (respuesta.status === 401) {
        return { fase: 'error', mensaje: MENSAJE_ACCESO_VENCIDO, reintentable: false }
      }
      if (respuesta.status === 503) {
        return { fase: 'error', mensaje: MENSAJE_SIN_CORTE, reintentable: true }
      }
      return { fase: 'error', mensaje: MENSAJE_ERROR_LECTURA, reintentable: true }
    }
    return { fase: 'listo', datos: (await respuesta.json()) as EstadoActualRespuesta }
  } catch {
    return { fase: 'error', mensaje: MENSAJE_ERROR_LECTURA, reintentable: true }
  }
}

/**
 * Pantalla "estado actual" del director (spec §6 y §17).
 *
 * Pide GET /api/problematicas/parte y muestra, en el orden de la
 * especificación: estado del servicio educativo, situación del
 * establecimiento, situación hidrometeorológica en seguimiento con sus
 * afectaciones vigentes, última actualización y acciones. La identificación
 * del establecimiento (punto 1 de §6) la resuelve la página del servidor, que
 * ya la conoce: así el director la reconoce sin esperar a la red.
 *
 * Dos reglas que este componente no puede romper:
 *  - `servicio.estadoGeneral` llega derivado del servidor (spec §3.4). Acá no
 *    se recalcula ni se ofrece "parcialmente suspendidas" como algo elegible.
 *  - El director no puede cerrar ni resolver la situación (spec §18.9). No
 *    existe ninguna acción de ese tipo en esta pantalla, ni deshabilitada.
 */
export function EstadoActualParte({ cue }: { cue: string }): JSX.Element {
  const [estado, setEstado] = useState<Estado>({ fase: 'cargando' })
  const [intento, setIntento] = useState(0)

  useEffect(() => {
    let vigente = true
    void obtenerEstado(cue).then((siguiente) => {
      if (vigente) setEstado(siguiente)
    })
    return () => {
      vigente = false
    }
  }, [cue, intento])

  function reintentar() {
    setEstado({ fase: 'cargando' })
    setIntento((n) => n + 1)
  }

  if (estado.fase === 'cargando') {
    // Nielsen #1: la espera se anuncia en vez de dejar la pantalla en blanco.
    return (
      <p className="estado-actual-aviso" role="status">
        Buscando el estado actual del establecimiento…
      </p>
    )
  }

  if (estado.fase === 'error') {
    return (
      <div className="estado-actual-aviso" role="alert">
        <p className="estado-actual-aviso__texto">{estado.mensaje}</p>
        {estado.reintentable && (
          <Button type="button" onClick={reintentar}>
            Reintentar
          </Button>
        )}
        {estado.mensaje === MENSAJE_ACCESO_VENCIDO && (
          <a
            className="ui-button ui-button--default"
            href={enlaceCon('/problematicas/parte', cue)}
          >
            Volver a ingresar la contraseña
          </a>
        )}
      </div>
    )
  }

  const { datos } = estado
  const sinSituacion = sinSituacionEnSeguimiento(datos)
  const afectaciones = datos.afectaciones ?? []
  const rigeServicio = formatearMomento(rigeDesdeDelServicio(datos.servicio?.alcanceVigente))
  const rigeEstablecimiento = formatearMomento(datos.parte?.estadoEstablecimientoRigeDesde)
  const ultimaActualizacion = formatearMomento(datos.ultimaActualizacion)

  return (
    <div className="estado-actual">
      {datos.parte && datos.servicio && (
        <section className="estado-actual-bloque" aria-labelledby="estado-actual-servicio">
          <h2 className="estado-actual-bloque__titulo" id="estado-actual-servicio">
            Estado del servicio educativo
          </h2>
          <p className="estado-actual-bloque__valor">{ETIQUETA_SERVICIO[datos.servicio.estadoGeneral]}</p>
          {rigeServicio && (
            <p className="estado-actual-bloque__vigencia">Rige desde el {rigeServicio}</p>
          )}
          <a
            className="ui-button ui-button--secondary estado-actual-bloque__accion"
            href={enlaceCon('/problematicas/parte/actualizar', cue, 'servicio')}
            aria-label="Informar un cambio en el servicio educativo"
          >
            Informar un cambio
          </a>
        </section>
      )}

      {datos.parte && (
        <section className="estado-actual-bloque" aria-labelledby="estado-actual-establecimiento">
          <h2 className="estado-actual-bloque__titulo" id="estado-actual-establecimiento">
            Situación del establecimiento
          </h2>
          <p className="estado-actual-bloque__valor">
            {ETIQUETA_ESTABLECIMIENTO[datos.parte.estadoEstablecimiento]}
          </p>
          {rigeEstablecimiento && (
            <p className="estado-actual-bloque__vigencia">Rige desde el {rigeEstablecimiento}</p>
          )}
          <a
            className="ui-button ui-button--secondary estado-actual-bloque__accion"
            href={enlaceCon('/problematicas/parte/actualizar', cue, 'establecimiento')}
            aria-label="Informar un cambio en la situación del establecimiento"
          >
            Informar un cambio
          </a>
        </section>
      )}

      <section
        className="estado-actual-bloque estado-actual-bloque--ancho"
        aria-labelledby="estado-actual-situacion"
      >
        <h2 className="estado-actual-bloque__titulo" id="estado-actual-situacion">
          Situación hidrometeorológica en seguimiento
        </h2>

        {sinSituacion ? (
          <>
            <p className="estado-actual-bloque__vacio">{MENSAJE_SIN_SITUACION}</p>
            <a
              className="ui-button ui-button--default estado-actual-acciones__principal"
              href={enlaceCon('/problematicas/parte/nuevo', cue)}
            >
              Iniciar un reporte
            </a>
          </>
        ) : (
          <ul className="estado-actual-afectaciones">
            {afectaciones.map((afectacion) => (
              <EstadoActualAfectacion key={afectacion.id} afectacion={afectacion} />
            ))}
          </ul>
        )}
      </section>

      {(ultimaActualizacion || !sinSituacion) && (
        <footer className="estado-actual-pie">
          {ultimaActualizacion && (
            <p className="estado-actual-pie__actualizacion">Última actualización: {ultimaActualizacion}</p>
          )}
          {!sinSituacion && (
            <div className="estado-actual-acciones">
              <a
                className="ui-button ui-button--default estado-actual-acciones__principal"
                href={enlaceCon('/problematicas/parte/actualizar', cue)}
              >
                Actualizar el parte
              </a>
              <a
                className="ui-button ui-button--secondary"
                href={enlaceCon('/problematicas/parte/historial', cue)}
              >
                Ver historial
              </a>
            </div>
          )}
        </footer>
      )}
    </div>
  )
}

import type { Client } from '@libsql/client'
import { normalizeCue } from './cue'
import { getCorteVigente } from './ge-db'
import { listarIdentidadesPorPersonasDesdeGeDb } from './identidad'

export interface AlumnoContexto {
  gePersonId: number
  nombre: string
  apellido: string
}

export interface SeccionContexto {
  // Clave estable de la sección (= establecimientoCursoDivisionId de GE). NO es dato
  // personal: es el identificador institucional con el que el formulario informa qué
  // secciones selecciona, y el que POST /api/problematicas valida contra ge_seccion.
  geSectionId: number
  curso: string
  division: string
  nivel: string
  turno: string
  matricula: number
  // Antes este comentario decía que ge_person_id y cualquier identidad de
  // alumno estaban prohibidos en este payload. Eso cambió: el titular del
  // dato pidió que el formulario público permita seleccionar alumnos
  // individuales (no sólo secciones enteras), amparado en la contraseña
  // temporal de acceso (ver lib/infraestructura/acceso-publico.ts). Mientras
  // esa contraseña siga siendo el único gate, este payload SÍ puede llevar
  // identidad de alumnos. Cuando la reemplace la autenticación por token,
  // revisar si esta decisión sigue vigente.
  alumnos: AlumnoContexto[]
}

export interface NivelContexto {
  nivel: string
  secciones: SeccionContexto[]
}

export interface TurnoContexto {
  turno: string
  niveles: NivelContexto[]
}

export interface EscuelaContexto {
  cueAnexo: string
  nombre: string
  departamento: string
  localidad: string
}

export interface ContextoCue {
  escuela: EscuelaContexto
  turnos: TurnoContexto[]
}

export type ContextoErrorKind =
  | 'cue_ausente'
  | 'cue_invalido'
  | 'sin_corte_vigente'
  | 'cue_inexistente'
  | 'sin_secciones'

export interface ContextoError {
  kind: ContextoErrorKind
}

export type ContextoResultado = { ok: true; contexto: ContextoCue } | { ok: false; error: ContextoError }

interface SeccionRow {
  curso: string
  division: string
  nivel: string
  turno: string
  geSectionId: number
  matricula: number
}

function agruparPorTurnoYNivel(secciones: SeccionContexto[]): TurnoContexto[] {
  const turnos: TurnoContexto[] = []
  for (const seccion of secciones) {
    let turno = turnos.find((t) => t.turno === seccion.turno)
    if (!turno) {
      turno = { turno: seccion.turno, niveles: [] }
      turnos.push(turno)
    }
    let nivel = turno.niveles.find((n) => n.nivel === seccion.nivel)
    if (!nivel) {
      nivel = { nivel: seccion.nivel, secciones: [] }
      turno.niveles.push(nivel)
    }
    nivel.secciones.push(seccion)
  }
  return turnos
}

// Resuelve el contexto público de un CUE: localización, secciones con matrícula
// agregada y, por sección, la lista de sus alumnos (nombre y apellido, ya
// descifrados). Incluir identidad de alumnos acá es la excepción documentada
// en SeccionContexto: sólo llega a quien ya pasó la contraseña temporal de
// acceso público, nunca a un llamador sin ese gate.
export async function resolverContextoPorCue(
  client: Client,
  rawCue: string | null | undefined,
): Promise<ContextoResultado> {
  if (rawCue == null || rawCue.trim() === '') {
    return { ok: false, error: { kind: 'cue_ausente' } }
  }

  const identifier = normalizeCue(rawCue)
  if (!identifier) {
    return { ok: false, error: { kind: 'cue_invalido' } }
  }

  // La identidad de la escuela sale de ge_localizacion, que se siembra desde el
  // JSON versionado y no depende del padrón. Se resuelve ANTES que el corte: el
  // formulario público sólo necesita nombre y CUE para abrirse, y no tiene por
  // qué caerse entero porque el padrón nominal todavía no se importó. El corte
  // hace falta únicamente para ofrecer las secciones.
  const locRes = await client.execute({
    sql: 'SELECT cue_anexo as cueAnexo, nombre, departamento, localidad FROM ge_localizacion WHERE cue_anexo = ?',
    args: [identifier.value],
  })
  if (locRes.rows.length === 0) {
    return { ok: false, error: { kind: 'cue_inexistente' } }
  }
  const localizacion = locRes.rows[0]

  const corte = await getCorteVigente(client)

  // Una sola consulta con la matrícula ya agregada. Antes se hacía un COUNT por
  // sección: una escuela con cien secciones disparaba cien consultas.
  const seccionesRows = corte
    ? ((
        await client.execute({
          sql: `SELECT s.ge_section_id as geSectionId, s.curso, s.division, s.nivel, s.turno,
                       COUNT(DISTINCT a.ge_person_id) as matricula
                FROM ge_seccion s
                LEFT JOIN ge_alumno_seccion a
                  ON a.corte_id = s.corte_id AND a.ge_section_id = s.ge_section_id
                WHERE s.corte_id = ? AND s.cue_anexo = ?
                GROUP BY s.ge_section_id, s.curso, s.division, s.nivel, s.turno
                ORDER BY s.turno, s.nivel, s.curso, s.division`,
          args: [corte.id, identifier.value],
        })
      ).rows as unknown as SeccionRow[])
    : []

  // Alumnos por sección, en una sola consulta más allá de cuántas secciones
  // haya: mismo criterio anti-N+1 que la matrícula agregada de arriba. Los
  // nombres se descifran en un solo lote con todos los ge_person_id
  // involucrados, no sección por sección.
  const membresiaRows =
    corte && seccionesRows.length > 0
      ? (
          await client.execute({
            sql: `SELECT a.ge_section_id as geSectionId, a.ge_person_id as gePersonId
                  FROM ge_alumno_seccion a
                  JOIN ge_seccion s ON s.corte_id = a.corte_id AND s.ge_section_id = a.ge_section_id
                  WHERE a.corte_id = ? AND s.cue_anexo = ?`,
            args: [corte.id, identifier.value],
          })
        ).rows
      : []

  const personIdsPorSeccion = new Map<number, number[]>()
  const todosLosPersonIds = new Set<number>()
  for (const row of membresiaRows) {
    const geSectionId = Number(row.geSectionId)
    const gePersonId = Number(row.gePersonId)
    todosLosPersonIds.add(gePersonId)
    const lista = personIdsPorSeccion.get(geSectionId) ?? []
    lista.push(gePersonId)
    personIdsPorSeccion.set(geSectionId, lista)
  }

  const identidades = await listarIdentidadesPorPersonasDesdeGeDb(client, Array.from(todosLosPersonIds))
  const identidadPorPersona = new Map(identidades.map((i) => [i.gePersonId, i]))

  const secciones: SeccionContexto[] = seccionesRows.map((row) => {
    const geSectionId = Number(row.geSectionId)
    const personIds = personIdsPorSeccion.get(geSectionId) ?? []
    return {
      geSectionId,
      curso: String(row.curso),
      division: String(row.division),
      nivel: String(row.nivel),
      turno: String(row.turno),
      matricula: Number(row.matricula ?? 0),
      alumnos: personIds
        .map((id) => identidadPorPersona.get(id))
        .filter((a): a is AlumnoContexto => a !== undefined),
    }
  })

  return {
    ok: true,
    contexto: {
      escuela: {
        cueAnexo: String(localizacion.cueAnexo),
        nombre: String(localizacion.nombre),
        departamento: String(localizacion.departamento),
        localidad: String(localizacion.localidad),
      },
      turnos: agruparPorTurnoYNivel(secciones),
    },
  }
}

import { createClient, type Client } from '@libsql/client'
import path from 'node:path'
import { getDataDir } from '../data-dir'
import type { GeCorte } from './types'

// Subconjunto de Client que también satisface una Transaction de libsql:
// permite que attachGe y las consultas de impacto.ts / identidad.ts corran
// tanto sobre una conexión suelta como dentro de una transacción explícita
// (ver app/api/mapas/infraestructura/nominal/route.ts, que loguea el acceso
// en la misma transacción que sirve la respuesta).
export type EjecutorSql = Pick<Client, 'execute'>

export function getGeSqlitePath(): string {
  return path.join(getDataDir(), 'ge.sqlite')
}

const GE_DDL: string[] = [
  `CREATE TABLE IF NOT EXISTS ge_corte (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ciclo_lectivo INTEGER NOT NULL,
    fetched_at TEXT NOT NULL,
    estado TEXT NOT NULL CHECK (estado IN ('importando','vigente','historico'))
  )`,
  `CREATE TABLE IF NOT EXISTS ge_seccion (
    corte_id INTEGER NOT NULL,
    ge_section_id INTEGER NOT NULL,
    cue_anexo TEXT NOT NULL,
    curso TEXT NOT NULL,
    division TEXT NOT NULL,
    nivel TEXT NOT NULL,
    turno TEXT NOT NULL,
    PRIMARY KEY (corte_id, ge_section_id)
  )`,
  `CREATE TABLE IF NOT EXISTS ge_alumno_seccion (
    corte_id INTEGER NOT NULL,
    ge_section_id INTEGER NOT NULL,
    ge_person_id INTEGER NOT NULL,
    PRIMARY KEY (corte_id, ge_section_id, ge_person_id)
  )`,
  `CREATE TABLE IF NOT EXISTS ge_localizacion (
    cue_anexo TEXT PRIMARY KEY,
    cui TEXT,
    nombre TEXT NOT NULL,
    departamento TEXT NOT NULL,
    localidad TEXT NOT NULL,
    lat REAL,
    lon REAL,
    geo_calidad TEXT
  )`,
  `CREATE TABLE IF NOT EXISTS ge_alumno_identidad (
    ge_person_id INTEGER PRIMARY KEY,
    payload_cifrado TEXT NOT NULL
  )`,
  `CREATE INDEX IF NOT EXISTS idx_ge_seccion_corte_cue ON ge_seccion (corte_id, cue_anexo)`,
  `CREATE INDEX IF NOT EXISTS idx_ge_alumno_seccion_corte_section ON ge_alumno_seccion (corte_id, ge_section_id)`,
]

export function openGeDb(): Client {
  return createClient({ url: `file:${getGeSqlitePath()}` })
}

export async function ensureGeSchema(client: Client): Promise<void> {
  for (const stmt of GE_DDL) {
    await client.execute(stmt)
  }
}

// Monta ge.sqlite como base adjunta 'ge' de solo-lectura sobre una conexión existente (p.ej. la del Hub).
// NUNCA hardcodees la ruta: siempre getGeSqlitePath(). Escapá comillas simples en la ruta duplicándolas.
export async function attachGe(hostClient: EjecutorSql): Promise<void> {
  const gePath = getGeSqlitePath().replace(/'/g, "''")
  await hostClient.execute(`ATTACH DATABASE 'file:${gePath}?mode=ro' AS ge`)
}

export async function getCorteVigente(client: Client): Promise<GeCorte | null> {
  const res = await client.execute(
    "SELECT id, ciclo_lectivo as cicloLectivo, fetched_at as fetchedAt, estado FROM ge_corte WHERE estado = 'vigente' ORDER BY id DESC LIMIT 1",
  )
  if (res.rows.length === 0) return null
  const row = res.rows[0] as unknown as GeCorte
  return row
}

export async function activarCorte(client: Client, corteId: number): Promise<void> {
  const corte = await client.execute('SELECT id, estado FROM ge_corte WHERE id = ?', [corteId])
  if (corte.rows.length === 0) {
    throw new Error(`Corte ${corteId} no existe`)
  }
  const estado = corte.rows[0].estado as string
  if (estado !== 'importando') {
    throw new Error(`Corte ${corteId} no está en estado 'importando'`)
  }

  const seccionesSinLocalizacion = await client.execute(
    `SELECT COUNT(*) AS n FROM ge_seccion s
     WHERE s.corte_id = ? AND NOT EXISTS (
       SELECT 1 FROM ge_localizacion l WHERE l.cue_anexo = s.cue_anexo
     )`,
    [corteId],
  )
  const seccionesFallan = Number(seccionesSinLocalizacion.rows[0].n)
  if (seccionesFallan > 0) {
    throw new Error(`${seccionesFallan} secciones referencian cue_anexo inexistente en ge_localizacion`)
  }

  const membresiasHuerfanas = await client.execute(
    `SELECT COUNT(*) AS n FROM ge_alumno_seccion m
     WHERE m.corte_id = ? AND NOT EXISTS (
       SELECT 1 FROM ge_seccion s WHERE s.corte_id = m.corte_id AND s.ge_section_id = m.ge_section_id
     )`,
    [corteId],
  )
  const membresiasFallan = Number(membresiasHuerfanas.rows[0].n)
  if (membresiasFallan > 0) {
    throw new Error(`${membresiasFallan} membresías apuntan a ge_seccion inexistente`)
  }

  const tx = await client.transaction('write')
  try {
    await tx.execute({
      sql: "UPDATE ge_corte SET estado = 'historico' WHERE estado = 'vigente' AND id != ?",
      args: [corteId],
    })
    await tx.execute({ sql: "UPDATE ge_corte SET estado = 'vigente' WHERE id = ?", args: [corteId] })
    await tx.commit()
  } catch (err) {
    try {
      await tx.rollback()
    } catch {
      // noop: si el commit ya cerró la transacción, el error original manda
    }
    throw err
  }
}

